import sys
import csv
from statistics import mean, median

def is_number(s):
    try:
        float(s)
        return True
    except ValueError:
        return False

def main(filename):
    with open(filename, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        columns = reader.fieldnames
        data = {col: [] for col in columns}
        for row in reader:
            for col in columns:
                val = row[col]
                if is_number(val):
                    data[col].append(float(val))
        for col in columns:
            nums = data[col]
            if nums:
                print(f'{col}: mean={mean(nums):.2f}, median={median(nums):.2f}')
            else:
                print(f'{col}: no numeric data')

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python csvstats.py <csv_file>')
        sys.exit(1)
    main(sys.argv[1])
EOF

